<?php
namespace App\Services; use App\Models\{Cart,Product}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class CartService { public function current(?int $userId,?string $sessionId):Cart { return Cart::firstOrCreate($userId?['user_id'=>$userId]:['session_id'=>$sessionId]); } public function add(Cart $cart,Product $product,int $quantity):Cart { if($product->inventory?->available()<$quantity) throw ValidationException::withMessages(['quantity'=>'Insufficient stock.']); DB::transaction(function()use($cart,$product,$quantity){$item=$cart->items()->firstOrNew(['product_id'=>$product->id]);$item->quantity=($item->exists?$item->quantity:0)+$quantity;$item->unit_price=$product->price;$item->save();}); return $cart->fresh('items.product'); } public function totals(Cart $cart):array {$subtotal=(float)$cart->items->sum(fn($i)=>(float)$i->unit_price*$i->quantity);$discount=0;if($cart->coupon && $cart->coupon->is_active){$discount=$cart->coupon->type==='percent'?$subtotal*((float)$cart->coupon->value/100):min($subtotal,(float)$cart->coupon->value);}$tax=round(($subtotal-$discount)*.15,2);$shipping=$subtotal>=500?0:75;return compact('subtotal','discount','tax','shipping')+['total'=>round($subtotal-$discount+$tax+$shipping,2)];} }
